+        }
+
+        public static Converter read(StreamInput in) throws IOException {
+            return in.readEnum(EsqlConverter.class);
+        }
+
+        @Override
+        public Object convert(Object l) {
+            if (l == null) {
+                return null;
+            }
+            return converter.apply(l);
+        }
+    }
